function confirmCriticalAction(action){if(action.confirmCritical===true)return;let critical=false;if(action.type==='stock.post'){const st=S.stocks.find(x=>x.id===action.stockId);critical=Boolean(st&&part(st.partId)?.critical&&(action.kind==='出库'||action.kind==='损耗'));}if(action.type==='project.issue'){const p=S.projects.find(x=>x.id===action.projectId);critical=Boolean(p?.rows.some(x=>part(x.partId)?.critical));}if(critical){if(!window.confirm('本次会扣减关键元件，请确认型号、批次和数量后继续。'))throw Error('已取消关键元件操作');action.confirmCritical=true;}}
async function refinementAction(el){const a=el.dataset.act,id=el.dataset.id;if(a==='part-compare'){const p=part(id);if(!p)return true;const fields={category:'分类',value:'标称值',tolerance:'精度',voltage:'耐压',dielectric:'介质',package:'封装',manufacturer:'制造商'};openModal('参数核对',`<p class="modal-intro">将关键电气字段集中展示，BOM 匹配会把空缺标为“未知”，不会把单一文字命中当成适配确认。</p><div class="parameter-grid comparison">${Object.entries(fields).map(([k,v])=>`<div><dt>${v}</dt><dd>${esc(p[k]||'未填写')}</dd></div>`).join('')}</div><p class="helper">IC、MOS 管仍需结合厂商手册、驱动条件和实测记录确认。</p>`,{type:'part-compare'});return true;}if(a==='compare-pair'){const p=part(id),q=part(el.dataset.other);openModal('替代料参数对比',`<div class="table-scroll"><table><thead><tr><th>字段</th><th>${esc(p?.sku||'原元件')}</th><th>${esc(q?.sku||'替代料')}</th></tr></thead><tbody>${[['category','分类'],['package','封装'],['value','标称值'],['tolerance','精度'],['voltage','耐压'],['current','电流'],['power','功率'],['rdson','导通电阻'],['vgs','栅极驱动'],['polarity','沟道 / 极性'],['interface','接口']].map(([k,v])=>`<tr><td>${v}</td><td class="${p?.[k]!==q?.[k]?'different':''}">${esc(p?.[k]||'未填写')}</td><td class="${p?.[k]!==q?.[k]?'different':''}">${esc(q?.[k]||'未填写')}</td></tr>`).join('')}</tbody></table></div><p class="helper">差异只用于核对，系统不会仅凭相似参数自动认定可替代。</p>`,{type:'pair-compare'});return true;}if(a==='substitution-edit'){const sub=(S.substitutions||[]).find(x=>x.id===id);if(sub)substitutionForm(sub.partId,sub);return true;}return false;}
