function setConnection(ok){online=ok;$('#connectionStatus').innerHTML='<span class="online-dot '+(ok?'':'offline')+'"></span>'+(ok?'云端已连接':'离线快照');$('#saveState').textContent=ok?'库存已与云端同步':'正在等待云端恢复';$('#offlineBanner').hidden=ok;if(!ok)$('#offlineBanner').textContent='云端暂未连接，显示最后同步的库存（'+time(localStorage.getItem(cacheKey('synced-at')))+'）。可先保存草稿，联网核对后提交。';}
function acceptState(s){S=s;localStorage.setItem(cacheKey('cache'),JSON.stringify(s));localStorage.setItem(cacheKey('synced-at'),new Date().toISOString());}
function cacheKey(kind){return 'team-v2-'+(T.user?.id||'none')+'-'+space+'-'+kind;}
async function api(endpoint,{method='GET',body,auth=false,workspace=space}={}){
 if(body&&['action','transfer'].includes(endpoint))confirmCriticalAction(body);
 const epoch=T.epoch,controller=new AbortController(),timer=setTimeout(()=>controller.abort(),65000);let response,data;
 try{response=await fetch('/api/'+endpoint,{method,headers:{'Content-Type':'application/json','X-Workspace':workspace},signal:controller.signal,...(body!==undefined?{body:JSON.stringify(body)}:{})});const text=await response.text();try{data=JSON.parse(text);}catch{throw new Error('服务正在启动');}if(response.status>=500)throw new Error(data.error);}
 catch(e){if(epoch===T.epoch)setConnection(false);throw Object.assign(new Error('云端暂时无法连接，免费服务可能正在启动；已保存的库存和草稿仍可查看，请稍后重试。'),{network:true});}finally{clearTimeout(timer);}
 if(epoch!==T.epoch)throw new Error('元件库已切换，请在当前库重新操作');
 if(!response.ok){if(response.status===401&&!auth){clearIdentity();showAuthScreen('登录已失效，请重新登录');}if(response.status===403&&!auth){purgeCache(space);S=null;eventStream?.close();$('#page').innerHTML='<div class="panel"><h2>当前权限已变化</h2><p>请重新选择你有权访问的元件库。</p><button class="btn" data-act="team-switch">选择元件库</button></div>';closeModal();}throw Object.assign(new Error(data.error||'操作未完成'),{status:response.status});}
 if(!auth)setConnection(true);return data;
}
async function load(redraw=true){if(!T.user)throw new Error('请先登录');const r=await api('state');currentRole=r.role;acceptState(r.state);isLocal=r.local;remoteAccess=r.remoteAccess;const i=T.workspaces.findIndex(x=>x.id===space);if(i>=0)T.workspaces[i]=r.workspace;setConnection(true);if(redraw)render();return r;}
function connectEvents(){eventStream?.close();if(!T.user||document.hidden||!('EventSource' in window)||!online)return;const epoch=T.epoch;eventStream=new EventSource('/api/events?workspace='+encodeURIComponent(space));eventStream.onmessage=async e=>{if(epoch!==T.epoch)return;try{const incoming=JSON.parse(e.data);setConnection(true);if(incoming.revision!==T.team?.revision){await refreshIdentity();if(epoch!==T.epoch)return;}if(!S||incoming.rev!==S.rev){if($('#dialog').open){toast('库存已被其他成员更新，提交时会再次核对');return;}await load();}if(view==='team'&&!$('#dialog').open){await teamLoad();render();}}catch{}};eventStream.onerror=()=>setConnection(false);eventStream.addEventListener('unavailable',()=>setConnection(false));eventStream.addEventListener('revoked',async()=>{eventStream?.close();purgeCache(space);S=null;closeModal();try{await refreshIdentity();await switchWorkspace(T.workspaces[0]?.id);}catch{clearIdentity();showAuthScreen('设备或库权限已失效，请重新登录');}});}
async function mutate(action,requestId){
  if(pendingBatch())throw Error('有一批记账结果待确认，请到待同步草稿查询原批次后继续');
  if(!online)throw new Error('当前离线，请保存草稿后联网提交');
  saveStateText('正在保存本次操作…');
  let pendingApproval=false;
  try{
    const r=await api('action',{method:'POST',body:{...action,rev:S.rev,requestId:requestId||uid()}});
    acceptState(r.state);render();if(!r.pending&&action.type==='stock.post')rememberStock(action);
    if(r.pending){pendingApproval=true;saveStateText('已送交审批，库存尚未改变');closeModal();throw new Error('已提交管理员审批，库存尚未改变；请到成员与协作查看进度');}
    saveStateText('库存已与云端同步 · 刚刚');
    return r;
  }catch(e){if(!pendingApproval)saveStateText(e.network?'本次操作结果待确认，请联网核对流水后再操作':'本次操作未完成，请查看提示');throw e;}
}
