let authBusy=false;
function accountValidation(d){
 const name=String(d.username||'').trim();
 if(!name)return {field:'authUsername',message:'请输入账号'};
 if(d.mode==='register'&&!/^[\p{L}\p{N}_.@-]{3,40}$/u.test(name))return {field:'authUsername',message:'账号需为 3～40 位中英文、数字或 _ . @ -，不能包含空格'};
 if(!d.password)return {field:'authPassword',message:'请输入密码'};
 if(d.password.length>128||(d.mode==='register'&&d.password.length<8))return {field:'authPassword',message:'密码长度需为 8～128 位'};
 if(d.mode==='register'&&d.password!==d.confirmPassword)return {field:'authConfirm',message:'两次输入的密码不一致，请重新确认'};
 return null;
}
function authError(message,field){
 const box=$('#authError');if(!box)return;
 box.textContent=message;box.hidden=!message;
 for(const id of ['authUsername','authPassword','authConfirm'])$('#'+id)?.setAttribute('aria-invalid',String(id===field));
 if(message){const target=field?$('#'+field):box;target?.focus();}
}
