function applyRoleUI(){if(!S)return;const readonly=currentRole==='readonly';document.body.dataset.role=currentRole;const writes=new Set(['label-save','label-save-next','scan','scan-hub','add-part','edit-part','in','out','watch-add','bom-submit','bom-confirm','bom-post','inventory-bulk-out','bulk-out','project-new','project-edit','project-reserve','project-release','project-issue','project-procure','purchase-new','purchase-edit','purchase-receive','container-new','container-assign','container-stocktake','finished-new','draft-submit','batch-entry','batch-loss','batch-confirm','draft-batch','quick-loss','quick-count']);if(readonly)$$('[data-act]').forEach(x=>{if(writes.has(x.dataset.act)){x.disabled=true;x.title='只读成员无此操作权限';}});if(S.access?.restricted){const h=$('#page .page-head');if(h)h.insertAdjacentHTML('afterend','<p class="notice-info">当前仅显示你有权限的地点和项目；库存数量和导出范围以此为准。</p>');}}

