let draftSelected=new Set(),quoteQuantity=100;
function mobileNav(){return `<nav class="mobile-bottom" aria-label="手机主导航">${[['dashboard','grid','首页'],['inventory','box','元件'],['quick','plus','记账'],['projects','bom','项目'],['settings','settings','我的']].map(([v,i,t])=>`<button ${v==='quick'?'data-act="quick-menu"':`data-view="${v}"`} class="${view===v?'active':''}">${icon(i)}<span>${t}</span></button>`).join('')}</nav>`;}
function quickMenu(){openModal('快速记账',`<div class="quick-grid">${button('入库','in',true)}${button('领用','out',true)}${button('损耗','quick-loss')}${button('盘点','quick-count')}${button('BOM 入库 / 出库','bom-view')}${button(`待提交草稿 ${drafts().filter(d=>!d.approvalId).length} 笔`,'quick-drafts')}</div><p>最近使用的元件可在首页直接领用；断网时可先记录草稿。</p>`);}
function projectFromBom(){
 const rows=bom.rows.filter(r=>!(r.excluded&&!r.forceInclude)).map(r=>{const st=S.stocks.find(x=>x.id===r.stockId);const p=part(st?.partId||String(r.stockId||'').replace(/^new:/,''));
  const check=p?compareBomPart(r,p):null;if(check?.conflicts.length)throw Error('匹配规格冲突：'+check.conflicts.join('；'));const advice=check?[...check.unknowns,...check.differences].join('；'):'';
  if(!p&&matchDetails(r,S,bom.locationId).length)throw Error('有多个或待确认的匹配，请先选择准确的元件和库位');
  return {advice,partId:p?.id,autoPart:p?undefined:r.draft,perBoard:Number(r.perBoard),loss:Number(r.loss||0),reference:r.reference||''};
 });
 if(!rows.length||rows.some(r=>!r.partId&&!r.autoPart))throw Error('请先补全未匹配物料的型号与参数');
 openModal('保存项目，库存保持不变',tform('project-import',field('项目名称','name',bom.note||bom.filename.replace(/\.[^.]+$/,''),{required:true})+field('版本','version','')+`<p>共 ${rows.length} 行，其中 ${rows.filter(r=>!r.partId).length} 行需要建立资料。只建立零库存档案，不增加实物数量。</p><div class="table-scroll"><table><thead><tr><th>元件</th><th>每板</th><th>处理</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(part(r.partId)?.sku||r.autoPart.sku||r.autoPart.value)}${r.advice?`<small class="match-advice">${esc(r.advice)}</small>`:''}</td><td>${r.perBoard}</td><td>${r.partId?'关联已有元件':'零库存建档'}</td></tr>`).join('')}</tbody></table></div>`,'已核对规格，保存项目'),{rows,locationId:bom.locationId||S.locations[0]?.id,requestId:uid()});
}
function batchEntry(kind='出库'){
 const stocks=[...inventorySelected].map(id=>S.stocks.find(s=>s.id===id)).filter(Boolean);if(!stocks.length)throw Error('请在元件库全选或勾选需要处理的库位');
 openModal(kind==='损耗'?'批量登记损耗':'批量领用',tform('batch-entry',`<p>每个库位分别填写数量，填 0 表示本次跳过；确认后整批提交。</p><div class="table-scroll"><table><thead><tr><th>元件 / 库位</th><th>库存</th><th>本次数量</th></tr></thead><tbody>${stocks.map((st,i)=>`<tr><td>${esc(stockName(st))}</td><td>${st.qty}</td><td><input aria-label="${esc(part(st.partId)?.sku)}数量" name="qty-${i}" type="number" min="0" max="1000000000" value="0" required></td></tr>`).join('')}</tbody></table></div>`+field('用途 / 原因','note','',{required:true}),'核对整批数量'),{stocks,kind});
}
function pendingBatch(){try{return JSON.parse(localStorage.getItem(cacheKey('pending-batch'))||'null');}catch{return null;}}
async function reviewBatch(rows,draftIds=[]){
 if(pendingBatch()){showPendingBatch();return;}
 await load(false);const preview=batchPreview(S,rows);
 openModal('核对批量记账',`<p>以下按最新库存和清单顺序计算。全部通过才可提交，包含损耗或盘点时会遵循本库审批规则。</p><div class="table-scroll"><table><thead><tr><th>元件</th><th>动作</th><th>当前 → 提交后</th><th>核对</th></tr></thead><tbody>${preview.map(p=>`<tr><td>${esc(part(p.stock?.partId)?.sku||'库位不存在')}</td><td>${esc(p.row.kind)}</td><td>${p.before??'—'} → ${p.after??'—'}</td><td>${esc(p.error||'通过')}</td></tr>`).join('')}</tbody></table></div>${preview.some(p=>p.error)?'<p class="form-error">存在异常，整批不会提交。返回修改数量或取消勾选异常草稿。</p>':button('确认整批提交','batch-confirm',true)}${button('返回','close-modal')}`,{rows,draftIds,rev:S.rev,requestId:uid()});
}
function showPendingBatch(){const pending=pendingBatch();if(!pending)return;openModal('确认上一批提交结果',`<p>上一批 ${pending.rows.length} 条记录尚未取得明确结果。重试会沿用同一编号，不会重复扣账。</p>${button('查询 / 重试原批次','batch-retry',true)}`);}
async function sendBatch(retry=false){
 const payload=retry?pendingBatch():{...modalContext};if(!payload?.rows)throw Error('请重新核对清单');
 localStorage.setItem(cacheKey('pending-batch'),JSON.stringify(payload));
 try{
  const r=await api('action',{method:'POST',body:{type:'stock.batch',rows:payload.rows,rev:payload.rev,requestId:payload.requestId}});
  acceptState(r.state);
  if(payload.draftIds?.length)saveDrafts(r.pending?drafts().map(d=>payload.draftIds.includes(d.id)?{...d,approvalId:r.approvalId}:d):drafts().filter(d=>!payload.draftIds.includes(d.id)));
  localStorage.removeItem(cacheKey('pending-batch'));draftSelected.clear();inventorySelected.clear();closeModal();render();toast(r.pending?'已送交审批，实物库存尚未扣减':'整批记账成功');
 }catch(e){if(e.status){localStorage.removeItem(cacheKey('pending-batch'));}throw e;}
}
function draftsView(){const list=drafts(),active=list.filter(d=>!d.approvalId);return `${header('DRAFTS','待同步草稿','先选记录，再按最新库存整批核对。',button('快速领用','out',true))}<p>已确认快照：${time(localStorage.getItem(cacheKey('synced-at')))} · ${active.length} 笔待提交</p>${pendingBatch()?button('查询上一批提交结果','batch-pending',true):''}<div class="toolbar"><label><input id="draftSelectAll" type="checkbox" ${active.length&&active.every(d=>draftSelected.has(d.id))?'checked':''}> 全选待提交</label>${button(`核对已选 ${draftSelected.size} 笔`,'draft-batch',true)}${button('刷新审批结果','draft-approvals')}</div><div class="panel draft-list">${list.map(d=>{const st=S.stocks.find(s=>s.id===d.stockId);return `<article><label><input class="draft-check" data-draft="${d.id}" type="checkbox" ${draftSelected.has(d.id)?'checked':''} ${d.approvalId?'disabled':''}> ${esc(part(st?.partId)?.sku||'库位已变化')}</label><p>${esc(d.kind)} · ${d.qty} ${d.kind==='出库'?`× ${d.boards||1} 板 + 损耗 ${d.loss||0}`:''} · ${esc(d.note||'')}</p><small>记录时 ${d.snapshotQty}，当前 ${st?.qty??'—'} · ${time(d.createdAt)}</small>${d.approvalId?'<b>已送审批，等待处理</b>':button('核对提交','draft-review',false,`data-id="${d.id}"`)+button('删除草稿','draft-delete',false,`data-id="${d.id}"`)}</article>`;}).join('')||'<p>暂无待提交记录</p>'}</div>`;}
