function quotePanel(){const tracked=S.parts.filter(p=>p.watch||S.stocks.some(s=>s.partId===p.id));return `<section class="panel quote-panel"><h2>采购报价核对</h2><p>国际接口价格为 USD；国内人民币报价请按实际供应商记录。不同来源、币种和数量档分别比较。</p><label>计划购买数量 <input id="quoteQuantity" type="number" min="1" max="1000000000" value="${quoteQuantity}"></label><p>${tracked.filter(p=>!p.lcscCode).length} 种尚未绑定立创编号 · 最近成功获取 ${time(S.settings.lcscLastSync)}</p>${S.settings.lcscLastSyncError?`<p class="form-error">${esc(S.settings.lcscLastSyncError)}</p>`:''}<div class="table-scroll"><table><thead><tr><th>元件 / 立创编号</th><th>适用报价</th><th>来源 / 时间</th></tr></thead><tbody>${tracked.map(p=>{const quotes=quoteSelection(S.observations,p.id,quoteQuantity);return `<tr><td>${esc(p.sku)}<small>${esc(p.lcscCode||'未绑定')}</small></td><td>${quotes.map(q=>`${esc(q.currency)} ${q.price} / 个，${esc(q.quantityTier)} 起`).join('<br>')||'暂无该数量档报价'}</td><td>${quotes.map(q=>`${esc(quoteSource(q))} · ${time(q.asOf)}${Date.now()-Date.parse(q.asOf)>86400000?' · 已超过24小时':''}`).join('<br>')||'可在元件详情手动记录采购报价'}</td></tr>`;}).join('')}</tbody></table></div></section>`;}
